const results = [];

for (const item of items) {
  const d = item.json.body && typeof item.json.body === 'object' ? item.json.body : item.json;

  const eventid = d.eventid || '';
  const session = d.session || null;
  const src_ip = d.src_ip || null;
  const src_port = d.src_port || null;
  const username = d.username || null;
  const password = d.password || null;
  const input = d.input || null;
  const message = d.message || null;
  const timestamp = d.timestamp || new Date().toISOString();

  // GeoIP - best effort, don't block on failure
  let country = 'Desconocido';
  if (src_ip) {
    try {
      const geo = await this.helpers.httpRequest({ method: 'GET', url: `http://ip-api.com/json/${src_ip}?fields=country`, json: true, timeout: 2000 });
      if (geo && geo.country) country = geo.country;
    } catch (e) {
      // GeoIP failed, keep default
    }
  }

  // Los valores viajan como parámetros de la consulta ($1…$10), no se concatenan en el SQL.
  const port = src_port ? parseInt(src_port) : null;
  results.push({ json: { eventid, session, src_ip, src_port: port, username, password, input, message, timestamp, country } });
}

return results;
